import re

QS = r'"((?:[^"\\]|\\.)*)"'
TOK = re.compile(r'\bStr ' + QS + r'|(?<!")\b(Space|SoftBreak|LineBreak)\b(?!")')


def unq(s):
    return s.replace('\\"', '"').replace('\\\\', '\\')


def text(s):
    out = []
    for m in TOK.finditer(s):
        if m.group(1) is not None:
            out.append(unq(m.group(1)))
        elif m.group(2) == 'LineBreak':
            out.append('\n')
        else:
            out.append(' ')
    return re.sub(r' +', ' ', ''.join(out)).strip()


def rows(seg):
    res = []
    for part in re.split(r'[\[,]\s*Row\b', seg)[1:]:
        res.append([text(c) for c in re.split(r'[\[,]\s*Cell\b', part)[1:]])
    return res


def items(src, start):
    res = []
    depth = 0
    i = start
    ins = False
    st = 0
    while i < len(src):
        c = src[i]
        if ins:
            if c == '\\':
                i += 1
            elif c == '"':
                ins = False
        elif c == '"':
            ins = True
        elif c == '[':
            depth += 1
            if depth == 2:
                st = i
        elif c == ']':
            if depth == 2:
                res.append(text(src[st:i + 1]))
            depth -= 1
            if depth == 0:
                break
        i += 1
    return res


def parse(lines):
    elems = []
    skip = []
    cur = None
    for i, l in enumerate(lines):
        m = re.match(r'^[\[,] ?([A-Z]\w*)', l)
        if m:
            cur = [m.group(1), [i]]
            elems.append(cur)
        elif cur is not None and l.startswith(' ') and l.strip():
            cur[1].append(i)
        else:
            skip.append(i)
    heads = []
    hl = []
    paras = []
    pl = []
    lis = []
    ll = []
    oth = []
    ol = []
    tables = []
    nt = 0
    nl = 0
    sec = ''
    for typ, idx in elems:
        src = '\n'.join(lines[i] for i in idx)
        if typ == 'Header':
            m = re.search(r'Header\s+(\d+)\s*\(\s*' + QS, src)
            hid = unq(m.group(2)) if m else ''
            htext = text(src)
            heads.append({'level': int(m.group(1)) if m else '', 'id': hid, 'text': htext})
            hl += idx
            sec = hid or htext
        elif typ in ('Para', 'Plain'):
            links = re.findall(r'\bLink\b.*?\]\s*\(\s*' + QS, src, re.S)
            paras.append({'section': sec, 'type': typ, 'text': text(src), 'links': ' '.join(unq(x) for x in links)})
            pl += idx
        elif typ in ('BulletList', 'OrderedList'):
            nl += 1
            k = src.find('[', src.find(typ))
            its = items(src, k) if k >= 0 else []
            for n, it in enumerate(its):
                lis.append({'section': sec, 'list': nl, 'type': typ, 'item': n + 1, 'text': it})
            ll += idx
        elif typ == 'Table':
            nt += 1
            h = src.find('TableHead')
            b = src.find('TableBody')
            f = src.find('TableFoot')
            hr = rows(src[h:b]) if 0 <= h < b else []
            br = rows(src[b:f if f > b else len(src)]) if b >= 0 else []
            names = hr[0] if hr else []
            n = max([len(names)] + [len(r) for r in br])
            keys = []
            for j in range(n):
                k = names[j] if j < len(names) and names[j] else 'col%d' % (j + 1)
                if k in keys or k == 'section':
                    k = 'col%d' % (j + 1)
                keys.append(k)
            recs = []
            for r in br:
                rec = {'section': sec}
                for j in range(n):
                    rec[keys[j]] = r[j] if j < len(r) else ''
                recs.append(rec)
            tables.append({'name': 'table_%d' % nt, 'kind': 'table', 'lines': idx, 'records': recs})
        else:
            oth.append({'section': sec, 'type': typ, 'text': text(src)})
            ol += idx
    blocks = []
    if hl:
        blocks.append({'name': 'headers', 'kind': 'table', 'lines': hl, 'records': heads})
    if pl:
        blocks.append({'name': 'paragraphs', 'kind': 'table', 'lines': pl, 'records': paras})
    blocks += tables
    if ll:
        blocks.append({'name': 'list_items', 'kind': 'table', 'lines': ll, 'records': lis})
    if ol:
        blocks.append({'name': 'other_blocks', 'kind': 'table', 'lines': ol, 'records': oth})
    return {'blocks': blocks, 'skip': skip}
